import { ChangeDetectionStrategy, Component, computed, input, model, output, signal } from '@angular/core';
import { NzDropDownModule } from 'ng-zorro-antd/dropdown';
import { NzInputModule } from 'ng-zorro-antd/input';
import { NzCheckboxModule } from 'ng-zorro-antd/checkbox';
import { TablerIconComponent, IconBolt, IconX, IconCheck, IconChecks, IconMinus, IconSearch } from '@tabler/icons-angular';

export interface HrmQuickFilterOption {
  value: string;
  label: string;
  disabled?: boolean;
}

/** hrm-quick-filter — BỘ LỌC NHANH dạng pill trên toolbar (kiểu Shopify filter).
 *  Pill icon thunder + nhãn; bấm → panel (nz-dropdown) gồm ô tìm (nz-input, không dấu),
 *  hàng "Chọn tất cả" (chỉ mode multiple, divider dưới: ✓✓ khi chưa đủ → bấm chọn hết;
 *  đã đủ → − đỏ "Bỏ chọn tất cả") và danh mục.
 *  2 chế độ: `mode="single"` (chọn 1, không checkbox — ✓ phải, chọn xong tự đóng) /
 *  `mode="multiple"` (CHECKBOX bên trái từng mục, nz-checkbox).
 *  Đã chọn: pill đổi VIỀN màu brand + hiện giá trị — 1 mục → tên mục; ≥2 → "N <unit>" (đếm, đậm hơn);
 *  nút ✕ ở pill xoá nhanh toàn bộ. Engine overlay/search = ng-zorro; toàn bộ skin = design token.
 *  <hrm-quick-filter label="Ngôn ngữ" unit="ngôn ngữ" [options]="opts" [(value)]="sel" />
 *  <hrm-quick-filter label="Sắp xếp" mode="single" [options]="sorts" [(value)]="sort" /> */
@Component({
  selector: 'hrm-quick-filter',
  imports: [NzDropDownModule, NzInputModule, NzCheckboxModule, TablerIconComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <button type="button" class="qf" [class.qf--active]="value().length > 0"
      nz-dropdown [nzDropdownMenu]="panel" nzTrigger="click" [nzVisible]="open()" (nzVisibleChange)="onVisible($event)">
      @if (value().length > 0) {
        <span class="qf-x" role="button" [attr.aria-label]="clearLabel() || null"
          (click)="clear($event)"><tabler-icon [icon]="xIcon" [size]="14" /></span>
      } @else {
        <tabler-icon class="qf-ic" [icon]="$any(icon())" [size]="15" />
      }
      <span class="qf-label">{{ label() }}</span>
      @if (value().length > 0) {
        <span class="qf-sep"></span>
        <span class="qf-count">{{ display() }}</span>
      }
    </button>

    <nz-dropdown-menu #panel>
      <div class="qf-panel">
        @if (searchable()) {
          <div class="qf-search">
            <tabler-icon class="qf-search-ic" [icon]="searchIcon" [size]="15" />
            <input nz-input class="qf-search-in" type="text" [value]="query()" (input)="onSearch($event)"
              [attr.placeholder]="searchPlaceholder() || null" [attr.aria-label]="searchPlaceholder() || null" />
          </div>
        }
        @if (mode() === 'multiple') {
          <!-- Chọn tất cả: KHÔNG checkbox, có divider dưới. Chưa đủ/chưa chọn → ✓✓ "Chọn tất cả";
               đã chọn hết → − đỏ "Bỏ chọn tất cả". -->
          <button type="button" class="qf-row qf-all" [class.qf-all--clear]="allState() === 'all'" (click)="toggleAll()">
            <tabler-icon class="qf-all-ic" [icon]="allState() === 'all' ? minusIcon : checksIcon" [size]="16" />
            <span class="qf-row-label">{{ allState() === 'all' ? deselectAllLabel() : selectAllLabel() }}</span>
          </button>
        }
        <div class="qf-list" role="listbox" [attr.aria-multiselectable]="mode() === 'multiple'">
          @for (o of filtered(); track o.value) {
            <button type="button" class="qf-row" role="option" [attr.aria-selected]="isPicked(o.value)"
              [class.qf-row--picked]="isPicked(o.value)" [disabled]="o.disabled ?? false" (click)="pick(o)">
              @if (mode() === 'multiple') {
                <label nz-checkbox class="qf-cb" [nzChecked]="isPicked(o.value)" [nzDisabled]="o.disabled ?? false"></label>
              }
              <span class="qf-row-label">{{ o.label }}</span>
              <!-- Chọn 1: không checkbox — ✓ bên phải đánh dấu mục đang chọn. -->
              @if (mode() === 'single' && isPicked(o.value)) { <tabler-icon class="qf-tick" [icon]="checkIcon" [size]="16" /> }
            </button>
          }
          @if (!filtered().length) { <div class="qf-empty">{{ emptyText() }}</div> }
        </div>
      </div>
    </nz-dropdown-menu>
  `,
  host: { class: 'hrm-quick-filter' },
  styles: [`
:host { display: inline-block; }

/* Pill trigger */
.qf {
  display: inline-flex; align-items: center; gap: 6px;
  /* KHÔNG cố định pill: --radius-lg ăn theo --radius-scale của config theme Bo góc
     (Vuông ≈ 5px · Mặc định 10px · Bo tròn 16px = pill với chiều cao nút này). */
  padding: 5px 12px; border-radius: var(--radius-lg); cursor: pointer;
  background: var(--bg-surface); border: 1px solid var(--border-sub);
  font-family: var(--font-sans); font-size: var(--fs-13); color: var(--text-body);
  transition: border-color var(--duration-fast, .15s) var(--ease-out, ease),
              background var(--duration-fast, .15s) var(--ease-out, ease);
}
.qf:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }
/* Đã chọn: chỉ đổi viền sang brand (không đảo nền) — theo spec DS. */
.qf--active { border-color: var(--primary-base); }
.qf-ic { flex: none; color: var(--text-sub); }
.qf-x { flex: none; display: grid; place-items: center; width: 16px; height: 16px;
  border-radius: var(--radius-full); color: var(--text-sub); }
.qf-x:hover { color: var(--text-strong); background: var(--bg-surface-subtle); }
.qf-label { white-space: nowrap; }
.qf-sep { width: 1px; align-self: stretch; margin: 1px 2px; background: var(--border-sub); }
/* Số lượng/giá trị chọn — đậm hơn nhãn 1 nấc. */
.qf-count { white-space: nowrap; font-weight: 600; color: var(--text-strong); }
.qf:focus-visible { outline: 2px solid var(--primary-focus-ring, var(--primary-base)); outline-offset: 1px; }

/* Panel (render trong overlay nz-dropdown — vẫn là template của component nên style scoped ăn) */
.qf-panel {
  min-width: 240px; max-width: 320px; padding: 6px;
  background: var(--bg-surface); border: 1px solid var(--border-sub);
  border-radius: var(--radius-xl); box-shadow: var(--shadow-regular-md);
  font-family: var(--font-sans);
}
.qf-search { display: flex; align-items: center; gap: 8px; padding: 4px 10px 8px; border-bottom: 1px solid var(--border-soft); }
.qf-search-ic { flex: none; color: var(--text-soft); }
.qf-search-in.ant-input.ant-input {
  flex: 1; min-width: 0; padding: 4px 0; border: 0; background: transparent; box-shadow: none;
  font-size: var(--fs-13); color: var(--text-body);
}
.qf-search-in.ant-input::placeholder { color: var(--text-soft); }
/* Hàng "Chọn tất cả" — divider dưới tách khỏi danh mục, cùng tông divider phụ với ô tìm (border-soft).
   Prefix .qf-row để thắng rule .qf-row (border: 0) đứng sau — cùng specificity thì rule sau thắng. */
.qf-row.qf-all { border: 0; border-bottom: 1px solid var(--border-soft); border-radius: 0; margin-bottom: 4px; }
.qf-all-ic { flex: none; color: var(--text-sub); }
/* Đã chọn hết → hành động đảo là XOÁ: chữ + icon đỏ, hover giữ đỏ (chỉ nền đổi).
   Prefix .qf-row để thắng tie specificity với .qf-row:hover đứng sau. */
.qf-row.qf-all--clear,
.qf-row.qf-all--clear:hover:not(:disabled),
.qf-row.qf-all--clear .qf-all-ic { color: var(--error-base); }
.qf-list { max-height: 300px; overflow-y: auto; display: flex; flex-direction: column; }
.qf-row {
  display: flex; align-items: center; gap: 10px; width: 100%;
  padding: 8px 10px; border: 0; background: transparent; cursor: pointer;
  border-radius: var(--radius-md); text-align: left;
  font-family: inherit; font-size: var(--fs-13); color: var(--text-body);
}
.qf-row:hover:not(:disabled) { background: var(--bg-surface-subtle); color: var(--text-strong); }
.qf-row:disabled { color: var(--text-disabled); cursor: not-allowed; }
.qf-row--picked { color: var(--text-strong); }
/* Checkbox hiển-thị-thuần trong row — click/keyboard do row đảm nhận, chặn tương tác trực tiếp. */
.qf-cb { flex: none; pointer-events: none; }
.qf-cb ::ng-deep .ant-checkbox + span { display: none; }
.qf-row-label { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.qf-tick { flex: none; color: var(--text-strong); }
.qf-empty { padding: 14px 10px; font-size: var(--fs-13); color: var(--text-soft); text-align: center; }
  `],
})
export class HrmQuickFilter {
  /** Nhãn bộ lọc trên pill (VD "Ngôn ngữ"). */
  readonly label = input.required<string>();
  /** Danh mục lựa chọn. */
  readonly options = input<HrmQuickFilterOption[]>([]);
  /** single = chọn 1 (chọn xong tự đóng) · multiple = tick nhiều. */
  readonly mode = input<'single' | 'multiple'>('multiple');
  /** Giá trị đã chọn (two-way). single vẫn là mảng 0–1 phần tử để API đồng nhất. */
  readonly value = model<string[]>([]);
  /** Tabler icon trên pill khi CHƯA chọn (mặc định thunder). */
  readonly icon = input<unknown>(IconBolt);
  /** Đơn vị đếm khi chọn ≥2 (VD "ngôn ngữ" → "2 ngôn ngữ"). Bỏ trống dùng label thường. */
  readonly unit = input('');
  /** Bật ô tìm kiếm trong panel (lọc không dấu). */
  readonly searchable = input(true);
  /** Nhãn i18n — bên gọi cấp. */
  readonly searchPlaceholder = input('Tìm kiếm...');
  readonly selectAllLabel = input('Chọn tất cả');
  /** Nhãn khi ĐÃ chọn hết — bấm để xoá toàn bộ (hiện màu đỏ, icon −). */
  readonly deselectAllLabel = input('Bỏ chọn tất cả');
  readonly emptyText = input('Không có kết quả');
  readonly clearLabel = input('');
  /** Bấm ✕ xoá nhanh toàn bộ lựa chọn. */
  readonly cleared = output<void>();

  protected readonly xIcon = IconX;
  protected readonly checkIcon = IconCheck;
  protected readonly checksIcon = IconChecks;
  protected readonly minusIcon = IconMinus;
  protected readonly searchIcon = IconSearch;

  protected readonly open = signal(false);
  protected readonly query = signal('');
  protected onVisible(v: boolean): void {
    this.open.set(v);
    if (!v) this.query.set('');
  }

  protected onSearch(e: Event): void { this.query.set((e.target as HTMLInputElement).value); }

  /** Chuẩn hoá bỏ dấu tiếng Việt — tìm không phân biệt dấu/hoa-thường. */
  private norm(s: string): string {
    return (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[\u0111]/g, 'd');
  }
  protected readonly filtered = computed<HrmQuickFilterOption[]>(() => {
    const q = this.norm(this.query().trim());
    const opts = this.options();
    if (!q) return opts;
    return opts.filter((o) => this.norm(o.label).includes(q));
  });

  protected isPicked(v: string): boolean { return this.value().includes(v); }

  /** Trạng thái "Chọn tất cả": all → ✓, some → −, none → trống. */
  protected readonly allState = computed<'all' | 'some' | 'none'>(() => {
    const n = this.value().length;
    const total = this.options().filter((o) => !o.disabled).length;
    return n === 0 ? 'none' : n >= total ? 'all' : 'some';
  });

  /** Hiện trên pill: 1 mục → tên mục; ≥2 → "N <unit|label>". */
  protected readonly display = computed<string>(() => {
    const v = this.value();
    if (v.length === 1) {
      return this.options().find((o) => o.value === v[0])?.label ?? v[0];
    }
    return `${v.length} ${this.unit() || this.label().toLowerCase()}`;
  });

  protected pick(o: HrmQuickFilterOption): void {
    if (o.disabled) return;
    if (this.mode() === 'single') {
      this.value.set([o.value]);
      this.open.set(false);
      return;
    }
    const cur = this.value();
    this.value.set(cur.includes(o.value) ? cur.filter((x) => x !== o.value) : [...cur, o.value]);
  }

  protected toggleAll(): void {
    const all = this.options().filter((o) => !o.disabled).map((o) => o.value);
    this.value.set(this.allState() === 'all' ? [] : all);
  }

  protected clear(e: Event): void {
    e.stopPropagation();
    this.value.set([]);
    this.open.set(false);
    this.cleared.emit();
  }
}
